{
  "imports": [
    "from decimal import Decimal",
    "import pytest",
    "from ledger.payroll import weekly_pay"
  ],
  "tests": [
    {
      "name": "test_weekly_pay_overtime_example",
      "intent": "the example from the task: 45 hours at 20.00 should pay 950.00",
      "code": "# intent: the example from the task: 45 hours at 20.00 should pay 950.00\ndef test_weekly_pay_overtime_example():\n    assert weekly_pay(Decimal(\"45\"), Decimal(\"20.00\")) == Decimal(\"950.00\")\n"
    },
    {
      "name": "test_weekly_pay_exactly_40_hours_no_overtime",
      "intent": "boundary: exactly 40 hours should not trigger overtime",
      "code": "# intent: boundary: exactly 40 hours should not trigger overtime\ndef test_weekly_pay_exactly_40_hours_no_overtime():\n    assert weekly_pay(Decimal(\"40\"), Decimal(\"20.00\")) == Decimal(\"800.00\")\n"
    },
    {
      "name": "test_weekly_pay_just_over_40_hours",
      "intent": "boundary: 40.01 hours should include one minute of overtime",
      "code": "# intent: boundary: 40.01 hours should include one minute of overtime\ndef test_weekly_pay_just_over_40_hours():\n    assert weekly_pay(Decimal(\"40.01\"), Decimal(\"20.00\")) == Decimal(\"800.30\")\n"
    },
    {
      "name": "test_weekly_pay_zero_hours",
      "intent": "zero hours should pay zero",
      "code": "# intent: zero hours should pay zero\ndef test_weekly_pay_zero_hours():\n    assert weekly_pay(Decimal(\"0\"), Decimal(\"20.00\")) == Decimal(\"0.00\")\n"
    },
    {
      "name": "test_weekly_pay_negative_hours_raises",
      "intent": "negative hours should raise ValueError",
      "code": "# intent: negative hours should raise ValueError\ndef test_weekly_pay_negative_hours_raises():\n    with pytest.raises(ValueError):\n        weekly_pay(Decimal(\"-1\"), Decimal(\"20.00\"))\n"
    },
    {
      "name": "test_weekly_pay_rounding_to_cents",
      "intent": "result should be rounded to cents using ROUND_HALF_UP",
      "code": "# intent: result should be rounded to cents using ROUND_HALF_UP\ndef test_weekly_pay_rounding_to_cents():\n    assert weekly_pay(Decimal(\"41\"), Decimal(\"10.005\")) == Decimal(\"410.21\")\n"
    }
  ]
}
